for(const golden of tcodeGoldens) test(`executed original C# TCode precision ${golden.precision}: ${golden.rows.length} midpoint/neighborhood records`,()=>{
  assert.equal(provenance.executedCSharp,true);
  const profile={precision:golden.precision,revision:0,axisOrder:['L0'],maximumDurationMs:2147483647,maximumPayloadBytes:1024};
  for(const row of golden.rows) {
    if(typeof row.value!=='number'||!Number.isFinite(row.value)||row.value<0||row.value>1) {
      assert.throws(()=>encodeFixed(profile,[{axisId:'L0',value:Number(row.value)}],0,true), e=>e.code==='invalidValue'); continue;
    }
    assert.equal(encodeFixed(profile,[{axisId:'L0',value:row.value}],0,true),row.encoded+'\n',`value ${row.value}; scaled ${row.scaled}`);
  }
  for(const row of golden.intervalRows) {
    const ms=Number(row.intervalMs);
    if(!Number.isFinite(ms)||ms<0) {assert.throws(()=>encodeFixed(profile,[{axisId:'L0',value:.5}],ms,false),e=>e.code==='invalidDuration');continue;}
    assert.equal(encodeFixed(profile,[{axisId:'L0',value:.5}],ms,false),row.encoded+'\n',`interval ${ms}`);
  }
});
test(`executed original C# range helpers: ${rangeGoldens.length} independent operations`,()=>{
  for(const row of rangeGoldens) {
    const input=row.input, range={axisId:'L0',minimum:input.minimum,maximum:input.maximum,enabled:true};
    const operation=input.operation==='middleSetAction'?'setMiddleAction':input.operation;
    const actual=RangeEditor[operation](range,input.value);
    assert.equal(actual.minimum,row.minimum,JSON.stringify(input));
    assert.equal(actual.maximum,row.maximum,JSON.stringify(input));
  }
});
